#pragma once
#include "common.hpp"
namespace snuw {
inline std::wstring outputName(const std::string& name,const std::wstring& fallback){auto value=wide(name);for(auto& c:value)if(c<32||std::wstring(L"<>:\"/\\|?*").find(c)!=std::wstring::npos)c=L'_';while(!value.empty()&&(value.back()==L'.'||value.back()==L' '))value.pop_back();if(value.empty()||value==L"."||value==L"..")value=fallback;if(value.size()>50)value.resize(50);auto stem=value.substr(0,value.find(L'.'));std::transform(stem.begin(),stem.end(),stem.begin(),::towupper);if(stem==L"CON"||stem==L"PRN"||stem==L"AUX"||stem==L"NUL"||(stem.size()==4&&(stem.substr(0,3)==L"COM"||stem.substr(0,3)==L"LPT")&&stem[3]>=L'1'&&stem[3]<=L'9'))value=L"_"+value;return value;}
inline bool storageId(const std::string& value,size_t length){return value.size()==length&&value.find_first_not_of("0123456789abcdef")==std::string::npos;}
inline fs::path outputDirectory(const json& cfg){auto root=fs::path(wide(str(cfg,"output")));auto owner=str(cfg,"_local_account_scope"),channel=str(cfg,"channel_id");if(!owner.empty()){if(!storageId(owner,64)||!storageId(channel,32))throw std::runtime_error("저장할 계정과 채널을 확인하세요.");return root/"data"/owner.substr(0,32)/channel/(str(cfg,"content_mode")=="hardcore"?"hardcore":"safe")/"images";}auto target=root/outputName(str(cfg,"creator_name"),L"User")/(str(cfg,"content_mode")=="hardcore"?L"Hardcore":L"Standard");auto folder=str(cfg,"folder_name");if(!folder.empty())target/=outputName(folder,L"Folder");return target/outputName(str(cfg,"channel_name"),L"Channel");}
inline fs::path imageMetadataPath(const fs::path& image){for(auto root=image.parent_path();!root.empty()&&root!=root.parent_path();root=root.parent_path()){if(fs::is_regular_file(root/L".snuw-layout-migration.json")){auto relative=image.lexically_relative(root/"images");if(!relative.empty()&&!relative.is_absolute()&&*relative.begin()!=L".."){auto target=root/"metadata"/relative;target.replace_extension(L".json");return target;}}if(fs::exists(root/L".snuw-output.json")){auto relative=image.lexically_relative(root);std::vector<fs::path> parts;for(auto& p:relative)parts.push_back(p);if(parts.size()>=6&&parts[0]==L"data"&&storageId(utf8(parts[1].wstring()),32)&&storageId(utf8(parts[2].wstring()),32)&&(parts[3]==L"safe"||parts[3]==L"hardcore")&&parts[4]==L"images"){auto target=root/parts[0]/parts[1]/parts[2]/parts[3]/"metadata";for(size_t i=5;i<parts.size();++i)target/=parts[i];target.replace_extension(L".json");return target;}if(parts.size()>=4){auto target=root/L"_metadata"/parts.front()/parts[parts.size()-2]/image.filename();target.replace_extension(L".json");return target;}break;}}auto path=image;path.replace_extension(L".json");return path;}
inline bool structuredHardcoreImage(const fs::path& image){for(auto root=image.parent_path();!root.empty()&&root!=root.parent_path();root=root.parent_path()){if(fs::is_regular_file(root/".snuw-layout-migration.json")){auto row=readJson(root/".snuw-layout-migration.json");return str(row,"mode")=="hardcore";}if(fs::is_regular_file(root/".snuw-output.json")){auto relative=image.lexically_relative(root);std::vector<fs::path> parts;for(auto& part:relative)parts.push_back(part);return parts.size()>=6&&parts[0]==L"data"&&storageId(utf8(parts[1].wstring()),32)&&storageId(utf8(parts[2].wstring()),32)&&parts[3]==L"hardcore"&&parts[4]==L"images";}}return false;}
}
